#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);

import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';

const rejectionProvider = (rejection: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw rejection;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const session = (): ChatSession => ({
  sessionId: 'non-error-rejection',
  userId: 'acceptance-test',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
});

describe('non-Error provider rejections', () => {
  it('calls onError with a cause-preserving Error and rethrows the original rejection', async () => {
    const plainObject = {reason: 'provider stopped'};
    const existingError = new Error('provider failed');
    const rejections: unknown[] = ['provider stopped', plainObject, undefined, existingError];
    const observations: Array<{
      rejection: unknown;
      hookCalls: number;
      hookReceivedError: boolean;
      hookReceivedOriginalError: boolean;
      cause: unknown;
      callerReceivedOriginal: boolean;
    }> = [];

    for (const rejection of rejections) {
      const hookErrors: Error[] = [];
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => void hookErrors.push(error),
      };
      const orchestrator = createChatOrchestrator(
        rejectionProvider(rejection),
        new PromptBuilder({identity: 'A test assistant.'}),
        undefined,
        {hooks}
      );

      let callerRejection: unknown;
      try {
        await orchestrator.processMessage(session());
      } catch (error) {
        callerRejection = error;
      }

      observations.push({
        rejection,
        hookCalls: hookErrors.length,
        hookReceivedError: hookErrors[0] instanceof Error,
        hookReceivedOriginalError: hookErrors[0] === rejection,
        cause: hookErrors[0]?.cause,
        callerReceivedOriginal: callerRejection === rejection,
      });
    }

    expect(observations).toEqual([
      {
        rejection: 'provider stopped',
        hookCalls: 1,
        hookReceivedError: true,
        hookReceivedOriginalError: false,
        cause: 'provider stopped',
        callerReceivedOriginal: true,
      },
      {
        rejection: plainObject,
        hookCalls: 1,
        hookReceivedError: true,
        hookReceivedOriginalError: false,
        cause: plainObject,
        callerReceivedOriginal: true,
      },
      {
        rejection: undefined,
        hookCalls: 1,
        hookReceivedError: true,
        hookReceivedOriginalError: false,
        cause: undefined,
        callerReceivedOriginal: true,
      },
      {
        rejection: existingError,
        hookCalls: 1,
        hookReceivedError: true,
        hookReceivedOriginalError: true,
        cause: undefined,
        callerReceivedOriginal: true,
      },
    ]);
  });
});
# Definition of Done

> A rejection that is not an `Error` — a thrown string, a plain object, a value from a library that rejects with its own shape — bypasses `onError` entirely while still propagating to the caller.

**Strategy: `direct`** — `createChatOrchestrator` exposes the real provider, hook, and caller boundaries through `processMessage`, so the rejection and both observations can be exercised without doubles.

## Done when these pass

- [ ] **calls onError with a cause-preserving Error and rethrows the original rejection** — A string, plain object, or `undefined` rejection reaches `onError` once as an `Error` preserving the raw value as `cause`, while the caller receives the original value; an existing `Error` reaches both unchanged.
  `src/orchestration/chatOrchestratorNonErrorRejection.acceptance.test.ts`

## Facets

- [ ] Normalize every non-`Error` rejection before calling `onError`, preserving the original value as `cause`.
- [ ] Rethrow the original rejection unchanged after the hook runs.
- [ ] Replace the spec's recorded flaw with the guaranteed rejection behavior and its acceptance-test link.
- [ ] Add a CHANGELOG entry explaining the newly reported non-`Error` rejections to existing consumers.
- [ ] Keep the existing `Error` hook tests unedited and green.
- [ ] Pass the repository's build, test, typecheck, eslint, and prettier checks.

## Out of scope

- `beforeSession` placement outside the orchestrator error boundary.
- Usage accounting across tool rounds (HALEngine#93).

`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.

## Installing hooks through config

- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L129)).
- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L221)).
- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L153)).
- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L116)).
- `afterModelResponse` is called once per user message after the round loop exits and is passed `totalUsage` — the sum of the usage every provider call in the turn reported, not the last round alone ([validated by: sums the usage of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L555)).

## Engine startup

- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L195)).

## Error reporting

- Every rejection calls `onError` once. A rejection that is not already an `Error` is wrapped in one with the original value as its `cause`; an existing `Error` is passed through unchanged, and the caller always receives the original rejection unchanged. ([validated by: calls onError with a cause-preserving Error and rethrows the original rejection](../../src/orchestration/chatOrchestratorNonErrorRejection.acceptance.test.ts#L24))
